export interface HelperError {
  code: string;
  message: string;
  panes?: unknown;
  pageCount?: number;
}

/** Read a non-2xx error once, including responses generated by a proxy rather than the helper. */
export async function readHelperError(response: Response): Promise<HelperError> {
  const body = await response.text().catch(() => '');
  const excerpt = body.trim().replace(/\s+/g, ' ').slice(0, 240);
  let detail: { code?: unknown; message?: unknown; panes?: unknown; pageCount?: unknown } | undefined;
  try { detail = JSON.parse(body)?.error; } catch { /* A proxy can return plain text or HTML. */ }
  return {
    code: typeof detail?.code === 'string' || typeof detail?.code === 'number' ? String(detail.code) : 'HTTP ' + response.status,
    message: typeof detail?.message === 'string' && detail.message.trim() ? detail.message : excerpt || 'request failed',
    panes: detail?.panes,
    pageCount: typeof detail?.pageCount === 'number' ? detail.pageCount : undefined,
  };
}
